/* global Office, Word */
import QRCode from 'qrcode';

Office.onReady((info) => {
  if (info.host === Office.HostType.Word) {
    document.getElementById("generate-btn").onclick = generateQRCode;
  }
});

async function generateQRCode() {
  const linkInput = document.getElementById("qr-link").value.trim();
  
  // 1. INPUT VALIDATION (Ported from VBA)
  if (linkInput.length === 0) {
    alert("The link can't be empty");
    return;
  }
  if (linkInput.length > 4000) {
    alert("The link is too long!");
    return;
  }

  // 2. RETRIEVE USER COLOR SELECTION (Using hex values matching your target colors)
  const selectedColor = document.querySelector('input[name="qr-color"]:checked').value;

  try {
    // 3. DYNAMIC SIZE CALCULATIONS (VBA Mathematical Formulas)
    const len = linkInput.length;
    const qrSize = Math.round(100 + 200 / Math.pow(len, len / 2000));
    const logo2QrRatio = (1 + 2 / Math.pow(len, len / 3500)) / 10;
    const logoSize = qrSize * logo2QrRatio;

    // 4. GENERATE THE BASE QR CODE VIA CANVAS
    const canvas = document.createElement("canvas");
    await QRCode.toCanvas(canvas, linkInput, {
      width: qrSize,
      margin: 1,
      errorCorrectionLevel: 'H', // High error correction to allow center overlay
      color: {
        dark: selectedColor,  // Dark modules match selected color
        light: '#FFFFFF'      // Background stays white
      }
    });

    const ctx = canvas.getContext("2d");

    // 5. EMBED THE REFINED LOGO (Passing the color to match your VBA PasteFormat logic)
    await drawCenterLogo(ctx, canvas.width, canvas.height, logoSize, selectedColor);

    // 6. CONVERT CANVAS TO BASE64 IMAGE DATA
    const base64Image = canvas.toDataURL("image/png").split(",")[1];

    // 7. INSERT INTO WORD
    await Word.run(async (context) => {
      const range = context.document.getSelection();
      const imageShape = range.insertInlinePictureFromBase64(base64Image, "Start");
      
      imageShape.width = qrSize * 0.75; 
      imageShape.height = qrSize * 0.75;
      imageShape.hyperlink = linkInput;

      await context.sync();
    });

  } catch (error) {
    console.error(error);
    alert("Error executing generation workflow: " + error.message);
  }
}

// Refined Helper Function to process color matching and clean background cutouts
function drawCenterLogo(ctx, canvasWidth, canvasHeight, logoSize, themeColor) {
  return new Promise((resolve) => {
    const img = new Image();
    
    img.onload = () => {
      const x = (canvasWidth - logoSize) / 2;
      const y = (canvasHeight - logoSize) / 2;
      
      // Step A: Create a temporary off-screen canvas to recolor the black logo image
      const offscreenCanvas = document.createElement("canvas");
      offscreenCanvas.width = logoSize;
      offscreenCanvas.height = logoSize;
      const oCtx = offscreenCanvas.getContext("2d");
      
      // Draw the original logo image onto the offscreen canvas
      oCtx.drawImage(img, 0, 0, logoSize, logoSize);
      
      // Get pixel data to change black pixels to your selected theme color
      const imgData = oCtx.getImageData(0, 0, logoSize, logoSize);
      const data = imgData.data;
      
      // Convert hexadecimal color to RGB components
      const r = parseInt(themeColor.slice(1, 3), 16);
      const g = parseInt(themeColor.slice(3, 5), 16);
      const b = parseInt(themeColor.slice(5, 7), 16);
      
      // Loop through all pixels. If a pixel is dark/black, change it to the theme color
      for (let i = 0; i < data.length; i += 4) {
        // If the pixel is not transparent and looks dark
        if (data[i + 3] > 10 && data[i] < 50 && data[i + 1] < 50 && data[i + 2] < 50) {
          data[i] = r;     // Red
          data[i + 1] = g; // Green
          data[i + 2] = b; // Blue
        }
      }
      oCtx.putImageData(imgData, 0, 0);
      
      // Step B: Draw a clean white ring mask on the main QR canvas to separate logo from modules
      ctx.fillStyle = "#FFFFFF";
      ctx.beginPath();
      // Draws a smooth circular white background boundary matching your target visual
      ctx.arc(canvasWidth / 2, canvasHeight / 2, (logoSize / 2) + 4, 0, Math.PI * 2);
      ctx.fill();
      
      // Step C: Stencil the newly recolored logo directly over the cutout ring
      ctx.drawImage(offscreenCanvas, x, y);
      
      resolve();
    };
    
    img.onerror = () => {
      resolve();
    };
    
    // Original high-resolution black drop logo asset string
    img.src = "data:image/png;base64,"; 
  });
}